// GPU 호출이 아닌, 이 단원의 명시적 계약을 검증하는 결정적 CPU 모델이다.
static unsigned checks = 0;
void Check(bool condition, const char* name) {
    ++checks;
    if (!condition) throw std::runtime_error(name); // Release에서도 검사를 유지한다.
}
template < class F > void Reject(F action, const char* name) {
    bool rejected = false;
    try {
        action();
    } catch (const std::exception&) {
        rejected = true;
    }
    Check(rejected, name);
}

// 정렬 덧셈과 범위 검사에 실패하면 원본 데이터를 변경하지 않는다.
std::uint64_t Align(std::uint64_t value, std::uint64_t alignment) {
    if (alignment == 0 || (alignment&(alignment-1)) != 0) throw std::invalid_argument("power of two");
    const auto extra = alignment-1;
    if (value > std::numeric_limits < std::uint64_t > ::max()-extra) throw std::overflow_error("alignment");
    return (value+extra)&~extra;
}
void Copy(std::vector < unsigned char > & dst, std::size_t offset, const std::vector < unsigned char > & src) {
    if (offset > dst.size() || src.size() > dst.size()-offset) throw std::out_of_range("buffer range");
    std::copy(src.begin(), src.end(), dst.begin()+static_cast < std::ptrdiff_t > (offset));
}
int main() {
    try {
        Check(Align(1, 256) == 256, "CBV alignment");
        Check(Align(256, 256) == 256, "already aligned");
        Check(Align(257, 256) == 512, "next slice");
        Check(Align(0, 256) == 0, "empty size");
        Reject([] { Align(7, 3); }, "not power of two");
        Reject([] { Align(7, 0); }, "zero align");
        Reject([] { Align(UINT64_MAX, 256); }, "overflow");
        std::vector < unsigned char > b(8, 0);
        Copy(b, 2, {7, 8});
        Check(b[2] == 7 && b[3] == 8, "copy bytes");
        auto old = b;
        Reject([&] { Copy(b, 7, {1, 2}); }, "range before mutation");
        Check(b == old, "preserve bytes");
        Copy(b, 8, {});
        Check(b == old, "empty end valid");
        std::cout << "PASS DX12-04: " << checks << " CPU contract checks\n";
        return 0;
    } catch (const std::exception& e) {
        std::cerr << e.what() << '\n';
        return 1;
    }
}

inline ComPtr<ID3D12Resource> Buffer(ID3D12Device* device, UINT64 bytes,
    D3D12_HEAP_TYPE heapType, D3D12_RESOURCE_STATES state,
    D3D12_RESOURCE_FLAGS flags = D3D12_RESOURCE_FLAG_NONE) {
    auto heap = Heap(heapType); auto desc = BufferDesc(bytes); desc.Flags = flags;
    ComPtr<ID3D12Resource> result;
    Check(device->CreateCommittedResource(&heap, D3D12_HEAP_FLAG_NONE, &desc, state,
        nullptr, IID_PPV_ARGS(result.GetAddressOf())), "CreateCommittedResource(buffer)");
    return result;
}
inline void Transition(ID3D12GraphicsCommandList* list, ID3D12Resource* resource,
    D3D12_RESOURCE_STATES before, D3D12_RESOURCE_STATES after) {
    if (before == after) return;
    D3D12_RESOURCE_BARRIER barrier{};
    barrier.Type = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
    barrier.Transition = {resource, D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES, before, after};
    list->ResourceBarrier(1, &barrier);
}
struct DeviceContext {
    ComPtr<IDXGIFactory6> factory;
    ComPtr<ID3D12Device> device;
    explicit DeviceContext(bool warp) {
        UINT factoryFlags = 0;
#ifndef NDEBUG
        // 개발 시 Graphics Tools 설치가 없으면 명확히 실패한다. 검증을 조용히 끄지 않는다.
        ComPtr<ID3D12Debug> debug;
        Check(D3D12GetDebugInterface(IID_PPV_ARGS(debug.GetAddressOf())), "D3D12 debug layer unavailable");
        debug->EnableDebugLayer(); factoryFlags = DXGI_CREATE_FACTORY_DEBUG;
#endif
        Check(CreateDXGIFactory2(factoryFlags, IID_PPV_ARGS(factory.GetAddressOf())), "CreateDXGIFactory2");
        ComPtr<IDXGIAdapter1> adapter;
        if (warp) {
            Check(factory->EnumWarpAdapter(IID_PPV_ARGS(adapter.GetAddressOf())), "EnumWarpAdapter");
            Check(D3D12CreateDevice(adapter.Get(), D3D_FEATURE_LEVEL_11_0,
                IID_PPV_ARGS(device.GetAddressOf())), "Create WARP device");
        } else {
            for (UINT index = 0; ; ++index) {
                adapter.Reset();
                HRESULT hr = factory->EnumAdapters1(index, adapter.GetAddressOf());
                if (hr == DXGI_ERROR_NOT_FOUND) break;
                Check(hr, "EnumAdapters1");
                DXGI_ADAPTER_DESC1 desc{}; Check(adapter->GetDesc1(&desc), "GetDesc1");
                if ((desc.Flags & DXGI_ADAPTER_FLAG_SOFTWARE) != 0) continue;
                if (SUCCEEDED(D3D12CreateDevice(adapter.Get(), D3D_FEATURE_LEVEL_11_0,
                    IID_PPV_ARGS(device.GetAddressOf())))) break;
            }
